target.css:
:root {
  --bg: #fdf6ec;
  --border: #d4a96a;
  --header-bg: #7a4f2e;
  --header-text: #fdf6ec;
  --subtext: #b07840;
  --key-text: #8a6040;
  --val-text: #3b2410;
  --divider: #e8d0b0;
  --footer-bg: #f3e4cc;
  --tag-bg: #7a4f2e;
  --tag-text: #fdf6ec;
  --date-bg: #e8d0b0;
  --date-text: #5a3820;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.candle-label {
  background-color: var(--bg);
  border: 2px solid var(--border);
  border-radius: 14px;
  width: 340px;
  overflow: hidden;
}

.label-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
}

.label-icon {
  font-size: 32px;
  line-height: 1;
}

.label-title {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.candle-name {
  font-size: 20px;
  font-weight: 700;
  color: var(--header-text);
  margin: 0;
  line-height: 1.2;
}

.candle-type {
  font-size: 12px;
  font-weight: 500;
  color: var(--subtext);
  margin: 0;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.label-details {
  padding: 12px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--divider);
}

.detail-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.detail-key {
  font-size: 12px;
  font-weight: 600;
  color: var(--key-text);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.detail-val {
  font-size: 14px;
  font-weight: 500;
  color: var(--val-text);
}

.label-footer {
  background-color: var(--footer-bg);
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 18px;
}

.batch-tag {
  background-color: var(--tag-bg);
  color: var(--tag-text);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.04em;
}

.date-tag {
  background-color: var(--date-bg);
  color: var(--date-text);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  border: 1px solid var(--border);
}

